import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.BjkiRu3Q.js";const b=JSON.parse('{"title":"Απαιτήσεις συστήματος","description":"","frontmatter":{},"headers":[],"relativePath":"el/system-requirements/index.md","filePath":"el/system-requirements/index.md"}'),i={name:"el/system-requirements/index.md"};function l(o,t,s,n,h,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="απαιτησεις-συστηματος" tabindex="-1">Απαιτήσεις συστήματος <a class="header-anchor" href="#απαιτησεις-συστηματος" aria-label="Permalink to &quot;Απαιτήσεις συστήματος&quot;">​</a></h1><p>Το TransferBook+ είναι πλατφόρμα διαχείρισης μεταφορών μέσω προγράμματος περιήγησης. Οι παρακάτω απαιτήσεις βοηθούν τους πελάτες να προετοιμάσουν τις συσκευές τους και τις τεχνικές ομάδες να αξιολογήσουν τη φιλοξενία.</p><div class="warning custom-block"><p class="custom-block-title">Συμβατότητα και χωρητικότητα</p><p>Πρόκειται για συστάσεις σχεδιασμού, όχι πιστοποιημένες ελάχιστες προδιαγραφές ή εγγύηση εμπορικής διαθεσιμότητας. Η έκδοση πηγαίου κώδικα αναφοράς αυτού του οδηγού είναι v0.7.13. Η πραγματική υποστήριξη εξαρτάται από την αποδεκτή εγκατάσταση, τις ενεργές λειτουργίες, τα δικαιώματα και τις δοκιμές συμβατότητας.</p></div><h2 id="συσκευες-και-προγραμματα-περιηγησης" tabindex="-1">Συσκευές και προγράμματα περιήγησης <a class="header-anchor" href="#συσκευες-και-προγραμματα-περιηγησης" aria-label="Permalink to &quot;Συσκευές και προγράμματα περιήγησης&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Στοιχείο</th><th>Προτεινόμενη βάση σχεδιασμού</th></tr></thead><tbody><tr><td>Λειτουργικό υπολογιστή</td><td>Υποστηριζόμενη από τον κατασκευαστή έκδοση Windows, macOS ή Linux</td></tr><tr><td>Λειτουργικό κινητού</td><td>Υποστηριζόμενη έκδοση Android ή iOS</td></tr><tr><td>Πρόγραμμα περιήγησης</td><td>Τρέχουσα σταθερή έκδοση Chrome, Edge, Firefox ή Safari, ανά συσκευή</td></tr><tr><td>Σταθμός γραφείου</td><td>Σύγχρονος επεξεργαστής δύο πυρήνων ή καλύτερος, 8 GB RAM</td></tr><tr><td>Οθόνη χειριστή</td><td>1920 × 1080 ή μεγαλύτερη· συνιστώνται πληκτρολόγιο και ποντίκι</td></tr><tr><td>Κινητή συσκευή</td><td>Οθόνη αφής, υποστηριζόμενος browser, αξιόπιστα δεδομένα κινητής ή Wi-Fi</td></tr><tr><td>Συνδεσιμότητα</td><td>Αξιόπιστη ευρυζωνική ή κινητή σύνδεση· συνιστάται εφεδρική σύνδεση για αναθέσεις</td></tr><tr><td>Ρυθμίσεις browser</td><td>Ενεργή JavaScript και απαραίτητα cookies πρώτου μέρους· πρόσβαση HTTPS</td></tr></tbody></table><p>Δεν απαιτείται εγκατάσταση εγγενούς εφαρμογής για πρόσβαση μέσω browser. Οι συνδυασμοί συσκευών και browser αποτελούν υποψήφιες επιλογές προς έλεγχο, όχι πιστοποιημένες πλατφόρμες. Μην θεωρείτε δεδομένη τη λειτουργία offline, παρακολούθηση στο παρασκήνιο, push ειδοποιήσεις ή εγγενή εφαρμογή.</p><h2 id="απαιτησεις-ανα-ρολο" tabindex="-1">Απαιτήσεις ανά ρόλο <a class="header-anchor" href="#απαιτησεις-ανα-ρολο" aria-label="Permalink to &quot;Απαιτήσεις ανά ρόλο&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ρόλος</th><th>Προετοιμασία</th></tr></thead><tbody><tr><td>Διαχειριστής εταιρείας</td><td>Υπολογιστής, εξουσιοδοτημένος λογαριασμός, πρόσβαση στις ρυθμίσεις εταιρείας</td></tr><tr><td>Χειριστής αναθέσεων</td><td>Υπολογιστής με επαρκή οθόνη, αξιόπιστο διαδίκτυο, δικαιώματα και ρυθμισμένα επιχειρησιακά δεδομένα</td></tr><tr><td>Οδηγός</td><td>Φορτισμένη κινητή συσκευή, αξιόπιστη σύνδεση και λογαριασμός· δικαιώματα τοποθεσίας μόνο για ενεργή λειτουργία που τα απαιτεί</td></tr><tr><td>Εμπορικός συνεργάτης</td><td>Υποστηριζόμενος browser και εξουσιοδοτημένη πρόσβαση συνεργάτη, όπου διατίθεται</td></tr><tr><td>Επιβάτης</td><td>Συσκευή με browser και ενεργό δημόσιο κανάλι κρατήσεων· δεν προϋποτίθεται λογαριασμός χειριστή</td></tr></tbody></table><p>Το email επιβάτη δεν είναι υποχρεωτικό για γρήγορες κρατήσεις. Χρησιμοποιήστε επιτρεπόμενο τρόπο επικοινωνίας χωρίς επινοημένες διευθύνσεις. Δείτε <a href="/el/tutorials/phone-only-booking.html">κράτηση μόνο με τηλέφωνο</a> και <a href="/el/plus/passenger-information.html">στοιχεία επιβάτη</a>.</p><h2 id="δικτυο-και-ασφαλεια" tabindex="-1">Δίκτυο και ασφάλεια <a class="header-anchor" href="#δικτυο-και-ασφαλεια" aria-label="Permalink to &quot;Δίκτυο και ασφάλεια&quot;">​</a></h2><ul><li>Χρησιμοποιήστε HTTPS στην εξουσιοδοτημένη εγκατάσταση και ενημερωμένο λειτουργικό και browser.</li><li>Χρησιμοποιήστε ατομικούς λογαριασμούς και δικαιώματα βάσει ρόλου. Μην μοιράζεστε διαπιστευτήρια.</li><li>Επιτρέψτε πρόσβαση HTTPS στην εγκεκριμένη εφαρμογή και μόνο στα ρητά ενεργοποιημένα endpoints τρίτων. Μην απενεργοποιείτε firewall ή επαλήθευση πιστοποιητικών.</li><li>Κλειδώνετε την οθόνη και μην αποθηκεύετε στοιχεία επιβατών σε μη διαχειριζόμενες συσκευές.</li><li>Ελέγχετε ώρα συστήματος, ζώνη ώρας και ρυθμίσεις browser. Σε διακοπή υποβολής, εξακριβώστε αν υπάρχει ήδη κράτηση ή πληρωμή πριν από επανάληψη.</li><li>Χρησιμοποιήστε μόνο συνθετικά στοιχεία επιβατών σε εγκεκριμένα περιβάλλοντα εκπαίδευσης ή staging.</li></ul><p>Δείτε <a href="/el/developers/authentication.html">ταυτοποίηση</a>, <a href="/el/developers/permissions.html">ρόλους και δικαιώματα</a> και <a href="/el/help/access-and-session.html">σφάλματα πρόσβασης</a>.</p><h2 id="απαιτησεις-διακομιστη-και-φιλοξενιας" tabindex="-1">Απαιτήσεις διακομιστή και φιλοξενίας <a class="header-anchor" href="#απαιτησεις-διακομιστη-και-φιλοξενιας" aria-label="Permalink to &quot;Απαιτήσεις διακομιστή και φιλοξενίας&quot;">​</a></h2><p>Η ενότητα αφορά τεχνικές ομάδες και παρόχους φιλοξενίας, όχι απλούς πελάτες. Η διαχειριζόμενη εγκατάσταση δεν απαιτεί Node.js ή PostgreSQL στον υπολογιστή πελάτη. Η αποκλειστική ή αυτοδιαχειριζόμενη φιλοξενία εξαρτάται από χωριστή έγκριση, υποστηριζόμενα πακέτα και ετοιμότητα. Δεν αποτελεί εμπορική προσφορά self-hosting.</p><table tabindex="0"><thead><tr><th>Στοιχείο</th><th>Προτεινόμενη βάση αξιολόγησης</th></tr></thead><tbody><tr><td>Λειτουργικό</td><td>Υποστηριζόμενο Linux 64 bit</td></tr><tr><td>CPU</td><td>4 vCPU</td></tr><tr><td>RAM</td><td>8 GB</td></tr><tr><td>Αποθήκευση</td><td>80 GB SSD/NVMe με παρακολούθηση χωρητικότητας</td></tr><tr><td>Runtime</td><td>Node.js 24 LTS ως αναφορά· επιβεβαιώστε την ακριβή υποστηριζόμενη έκδοση</td></tr><tr><td>Βάση</td><td>PostgreSQL 16 ως αναφορά· επιβεβαιώστε έκδοση και migrations</td></tr><tr><td>Reverse proxy</td><td>Apache ή NGINX με τερματισμό TLS</td></tr><tr><td>Διαχείριση υπηρεσίας</td><td>Επιτηρούμενη διεργασία με ελέγχους υγείας</td></tr><tr><td>Email και εξωτερικές υπηρεσίες</td><td>Εγκεκριμένα διαπιστευτήρια και σύνδεση μόνο για ενεργές διασυνδέσεις</td></tr><tr><td>Αντίγραφα</td><td>Αυτοματοποιημένα, προστατευμένα αντίγραφα βάσης και εφαρμογής· δοκιμασμένη επαναφορά</td></tr></tbody></table><p>Ο ελεγμένος κώδικας χρησιμοποιεί React/TypeScript, API Node.js/Express και PostgreSQL client. Οι εκτιμήσεις υλικού είναι αρχικές βάσεις. Δεν καθορίζεται εγγύηση χωρητικότητας, ταυτόχρονης χρήσης, καθυστέρησης ή διαθεσιμότητας.</p><h3 id="προυποθεσεις-εγκαταστασης" tabindex="-1">Προϋποθέσεις εγκατάστασης <a class="header-anchor" href="#προυποθεσεις-εγκαταστασης" aria-label="Permalink to &quot;Προϋποθέσεις εγκατάστασης&quot;">​</a></h3><ul><li>Οδηγίες build και migrations ανά έκδοση, ελεγμένα πακέτα και τεκμηριωμένο σχέδιο επαναφοράς.</li><li>Λογαριασμοί υπηρεσίας και βάσης με ελάχιστα δικαιώματα· μυστικά και κλειδιά υπογραφής εκτός δημόσιου περιεχομένου και Git.</li><li>Έγκυρα DNS και TLS, σωστό reverse proxy, περιορισμένη πρόσβαση βάσης, έλεγχοι υγείας και καταγραφή.</li><li>Ανεξάρτητα περιβάλλοντα παραγωγής, staging και demo. Ποτέ staging ως σιωπηρός στόχος παραγωγής.</li><li>Αντίγραφα με διατήρηση και δοκιμές επαναφοράς· παρακολούθηση σφαλμάτων, δίσκου, βάσης και λήξης πιστοποιητικών.</li><li>Χωριστή έγκριση και ολοκληρωμένες δοκιμές πληρωμών, ειδοποιήσεων, εξωτερικών αναθέσεων, χαρτών ή AI πριν την ενεργοποίηση.</li></ul><h2 id="αποδοχη-συμβατοτητας-και-χωρητικοτητας" tabindex="-1">Αποδοχή συμβατότητας και χωρητικότητας <a class="header-anchor" href="#αποδοχη-συμβατοτητας-και-χωρητικοτητας" aria-label="Permalink to &quot;Αποδοχή συμβατότητας και χωρητικότητας&quot;">​</a></h2><p>Πριν δημοσιευθούν πιστοποιημένες απαιτήσεις, ελέγξτε την ακριβή έκδοση στις προβλεπόμενες συσκευές και browser. Δοκιμάστε σύνδεση και λήξη συνεδρίας, κρατήσεις (με προαιρετικό email επιβάτη), πρόγραμμα, αναθέσεις, περιορισμούς ρόλων, κινητή ροή οδηγού, επαναφορά μετά από διακοπή δικτύου και ενεργές διασυνδέσεις. Μετρήστε χρήση πόρων και χρόνους απόκρισης σε αντιπροσωπευτικό φόρτο αιχμής και δοκιμάστε επαναφορά αντιγράφων. Καταγράψτε εκδόσεις, αποτελέσματα και περιορισμούς.</p><p>Δείτε <a href="/el/integrations/activation-and-channels.html">ετοιμότητα διασυνδέσεων</a> και <a href="/el/release-notes/">σημειώσεις εκδόσεων</a>.</p><p><a href="/system-requirements/">English</a></p><p>Για ένταξη και κύκλο εγκατάστασης δείτε <a href="/el/installation/">Εγκατάσταση και ανάπτυξη</a>.</p>',23)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
